BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL statement_timeout='20s';
SELECT jsonb_build_object(
 'observed_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'actor',current_user,
 'requested_rpc_overloads',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'signature',oidvectortypes(p.proargtypes),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) ORDER BY p.proname,oidvectortypes(p.proargtypes)),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname IN('create_catalog_calculator_with_audit','record_calculator_qa_decision','assign_calculator_reviewer','transition_calculator_with_audit','prepare_catalog_inventory_drafts','publish_calculator_batch_with_audit_v1')),
 'incoming_foreign_keys',(SELECT coalesce(jsonb_agg(jsonb_build_object('from_table',c.conrelid::regclass::text,'to_table',c.confrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conrelid::regclass::text,c.conname),'[]'::jsonb) FROM pg_constraint c WHERE c.contype='f' AND c.confrelid IN(SELECT t.oid FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname IN('platform_admins','calculator_catalog_admin','calculator_qa_checks','calculator_source_evidence','calculator_review_events','calculator_bulk_jobs','admin_alerts'))),
 'literal_table_reference_candidates',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'signature',oidvectortypes(p.proargtypes),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) ORDER BY n.nspname,p.proname,oidvectortypes(p.proargtypes)),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND (strpos(pg_get_functiondef(p.oid),'calculator_catalog_admin')>0 OR strpos(pg_get_functiondef(p.oid),'calculator_source_evidence')>0 OR strpos(pg_get_functiondef(p.oid),'calculator_qa_checks')>0 OR strpos(pg_get_functiondef(p.oid),'calculator_review_events')>0 OR strpos(pg_get_functiondef(p.oid),'platform_admins')>0)),
 'role_capabilities',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'superuser',rolsuper,'can_login',rolcanlogin,'bypass_rls',rolbypassrls,'public_create',has_schema_privilege(oid,'public','CREATE')) ORDER BY rolname) FROM pg_roles),
 'event_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'enabled',evtenabled,'owner',pg_get_userbyid(evtowner)) ORDER BY evtname),'[]'::jsonb) FROM pg_event_trigger),
 'session_groups',(SELECT coalesce(jsonb_agg(s),'[]'::jsonb) FROM(SELECT usename,application_name,state,count(*) AS count,count(*) FILTER(WHERE xact_start IS NOT NULL) AS transactions FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() GROUP BY usename,application_name,state ORDER BY usename,application_name,state)s),
 'prepared_transactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database())
) AS evidence;
ROLLBACK;
